from pathlib import Path
from urllib.parse import urlparse
import os
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
with sync_playwright() as p:
 b=p.webkit.launch(executable_path=os.environ['PLAYWRIGHT_WEBKIT_EXECUTABLE']) if os.getenv('GIF_TEST_BROWSER')=='webkit' else p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 c=b.new_context(viewport={'width':390,'height':844})
 def route(r):
  u=urlparse(r.request.url);f=ROOT/u.path.lstrip('/')
  if f.is_dir():f/='index.html'
  if u.hostname=='edit.test' and f.is_file():r.fulfill(body=f.read_bytes(),content_type={'.js':'application/javascript','.css':'text/css','.json':'application/json'}.get(f.suffix,'text/html'))
  else:r.fulfill(status=404)
 c.route('**/*',route);page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('https://edit.test/');page.evaluate('TreinoStorage.ready');students=[{'student_id':'dest','nome':'Destino Teste','treino':{'A':['Supino — 3×12'],'E':['Agachamento — 3×10']},'titulos':{'A':'A. Peito','E':'E. Pernas'}},{'student_id':'joao','nome':'João da Silva','treino':{'A':['Remada — 4×12 [Vídeo: https://youtu.be/SharedCopy12] [GIFs: https://drive.google.com/file/d/CopyGIF/view]'],'E':['Rosca — 3×10']},'titulos':{'A':'A. Costas','E':'E. Bíceps'},'historicoTreinos':[{'workout_id':'old-copy','name':'Anterior especial','treino':{'A':['Puxada — 2×15']},'titulos':{'A':'A. Costas anterior'}}]},{'student_id':'maria','nome':'Maria Oliveira','treino':{'B':['Extensora — 3×12']},'titulos':{'B':'B. Pernas'}}];page.evaluate('(s)=>localStorage.setItem("treinoAlunos",JSON.stringify(s))',students);page.reload();page.evaluate('TreinoStorage.ready');page.wait_for_function('document.querySelector("#searchName").value==="Destino Teste"');baseline=page.evaluate('JSON.parse(localStorage.getItem("treinoAlunos"))[1].treino');page.locator('.sec-e .copy-aluno-btn').click();modal=page.locator('#modalContent');search=modal.get_by_role('searchbox',name='Buscar aluno para copiar');expect(search).to_be_focused();expect(modal.locator('.aluno-list-item')).to_have_count(3);initialCount=3;expect(modal.locator('.aluno-list-item:visible')).to_have_count(initialCount);page.set_viewport_size({'width':320,'height':844});assert modal.evaluate('e=>e.scrollWidth<=e.clientWidth');search.fill('joao');assert modal.locator('.aluno-list-item:visible').count()==1;item=modal.locator('.aluno-list-item:visible');item.get_by_role('combobox',name='Seção de João da Silva').select_option('A');item.get_by_role('combobox',name='Versão de João da Silva').select_option('old-copy');item.get_by_role('button',name='👁 Visualizar treino').click();preview=page.locator('#copyPreviewDialog');expect(preview.locator('#copyPreviewExercises')).to_contain_text('Puxada');preview.locator('#copyPreviewClose').click();item.get_by_role('combobox',name='Versão de João da Silva').select_option('atual');item.get_by_role('combobox',name='Seção de João da Silva').select_option('A');item.get_by_role('button',name='👁 Visualizar treino').click();expect(preview.locator('#copyPreviewExercises')).to_contain_text('Remada');preview.locator('#copyPreviewConfirm').click();expect(page.locator('.sec-e ol')).to_contain_text('Remada');expect(page.locator('.sec-e h2')).to_have_text('E. Costas');expect(page.locator('.sec-a ol')).to_contain_text('Supino');page.wait_for_function('JSON.parse(localStorage.getItem("treinoAlunos"))[0].treino.E[0].includes("Remada")');saved=page.evaluate('JSON.parse(localStorage.getItem("treinoAlunos"))');assert 'SharedCopy12' in saved[0]['treino']['E'][0] and 'CopyGIF' in saved[0]['treino']['E'][0];assert saved[1]['treino']==baseline;page.locator('.sec-e .copy-aluno-btn').click();search.fill('inexistente');expect(modal.locator('#copyStudentEmpty')).to_be_visible();modal.get_by_role('button',name='Limpar busca de alunos').click();assert modal.locator('.aluno-list-item:visible').count()==initialCount;modal.locator('#closeModalBtn').click();expect(modal.locator('#copyStudentList')).not_to_be_visible();page.locator('#searchName').fill('');page.locator('#searchName').focus();expect(page.locator('#nameSuggestions')).to_be_visible();assert page.locator('#nameSuggestions').inner_text().find('João da Silva')>=0;assert not errors,errors;b.close();print('PASS: immediate student listing, accent-insensitive search/clear, section A to E, current/history preview, original student and media preserved, top name field lists people when empty')
